        Op.MSTORE(offset=Op.CALLDATALOAD(offset=0x0), value=0x60a7)
        + Op.POP(Op.MLOAD(offset=Op.CALLDATALOAD(offset=0x0)))
        + Op.MLOAD(offset=Op.CALLDATALOAD(offset=0x0)) + Op.STOP
